// === CONFIG ===
// El token compartido con el worker. Se lee de la variable de entorno HERMES_TOKEN del
// contenedor de n8n; si tu instancia bloquea $env, reemplaza '' por el token literal.
const TOKEN = (() => { try { return $env.HERMES_TOKEN || ''; } catch (e) { return ''; } })();

const entrada = $input.first().json;
const cabeceras = entrada.headers || {};
const cuerpo = entrada.body || {};
if (!TOKEN) { throw new Error('Falta HERMES_TOKEN en el entorno de n8n'); }
if ((cabeceras['x-hermes-token'] || '') !== TOKEN) { throw new Error('Token invalido'); }
const estado = $getWorkflowStaticData('global');
estado.lotes = estado.lotes || {};
const lote = String(cuerpo.lote || 'sin-lote');

estado.lotes[lote] = {
  host: cuerpo.host || '',
  carpetas: cuerpo.carpetas || 0,
  inventario: cuerpo.inventario || {},
  contadores: { hecho: 0, omitido: 0, dudoso: 0, error: 0 },
  procesados: 0,
  iniciado: Date.now(),
  ultimo_latido: Date.now(),
  cerrado: false,
};
estado.lote_activo = lote;
estado.accion = 'seguir';   // el mando puede cambiarla a 'pausa' o 'detener'
return [{ json: { ok: true, lote, inventario: cuerpo.inventario || {} } }];

// === CONFIG ===
// El token compartido con el worker. Se lee de la variable de entorno HERMES_TOKEN del
// contenedor de n8n; si tu instancia bloquea $env, reemplaza '' por el token literal.
const TOKEN = (() => { try { return $env.HERMES_TOKEN || ''; } catch (e) { return ''; } })();

const entrada = $input.first().json;
const cabeceras = entrada.headers || {};
const cuerpo = entrada.body || {};
if (!TOKEN) { throw new Error('Falta HERMES_TOKEN en el entorno de n8n'); }
if ((cabeceras['x-hermes-token'] || '') !== TOKEN) { throw new Error('Token invalido'); }
const estado = $getWorkflowStaticData('global');
estado.lotes = estado.lotes || {};
const lote = String(cuerpo.lote || 'sin-lote');

const registros = Array.isArray(cuerpo.registros) ? cuerpo.registros : [];
const info = estado.lotes[lote] || (estado.lotes[lote] = {
  contadores: { hecho: 0, omitido: 0, dudoso: 0, error: 0 }, procesados: 0,
  iniciado: Date.now(), inventario: {}, host: cuerpo.host || '', cerrado: false });
for (const r of registros) {
  const e = String(r.estado || 'desconocido');
  info.contadores[e] = (info.contadores[e] || 0) + 1;
  info.procesados = (info.procesados || 0) + 1;
}
info.ultimo_latido = Date.now();
// Solo metadatos: el worker nunca envia rutas, nombres ni contenido de los documentos.
return [{ json: { ok: true, lote, host: info.host, contadores: info.contadores,
                  procesados: info.procesados, n: registros.length, registros } }];

