const cuerpo = entrada.body || {};
if (!TOKEN) { throw new Error('Falta HERMES_TOKEN en el entorno de n8n'); }
if ((cabeceras['x-hermes-token'] || '') !== TOKEN) { throw new Error('Token invalido'); }
const estado = $getWorkflowStaticData('global');
estado.lotes = estado.lotes || {};
const lote = String(cuerpo.lote || 'sin-lote');

const info = estado.lotes[lote];
if (info) {
  info.ultimo_latido = Date.now();
  info.avance = cuerpo.avance || {};
}
const accion = String(estado.accion || 'seguir');
return [{ json: { accion, mensaje: estado.mensaje || '',
                  lote, ts: Date.now() } }];

// === CONFIG ===
const TOKEN = (() => { try { return $env.HERMES_TOKEN || ''; } catch (e) { return ''; } })();
const entrada = $input.first().json;
const consulta = entrada.query || {};
const cuerpo = entrada.body || {};
const token = (entrada.headers || {})['x-hermes-token'] || consulta.token || cuerpo.token || '';
if (!TOKEN || token !== TOKEN) { throw new Error('Token invalido'); }
const validas = ['seguir', 'pausa', 'detener'];
const accion = String(consulta.accion || cuerpo.accion || 'seguir');
if (!validas.includes(accion)) { throw new Error('accion debe ser: ' + validas.join(', ')); }
const estado = $getWorkflowStaticData('global');
estado.accion = accion;
estado.mensaje = String(consulta.mensaje || cuerpo.mensaje || '');
// El worker lee esto entre archivo y archivo: nunca corta un chat de Hermes por la mitad.
return [{ json: { ok: true, accion, mensaje: estado.mensaje, lote_activo: estado.lote_activo || '' } }];

// === CONFIG ===
// El token compartido con el worker. Se lee de la variable de entorno HERMES_TOKEN del
// contenedor de n8n; si tu instancia bloquea $env, reemplaza '' por el token literal.
const TOKEN = (() => { try { return $env.HERMES_TOKEN || ''; } catch (e) { return ''; } })();

const entrada = $input.first().json;
const cabeceras = entrada.headers || {};
const cuerpo = entrada.body || {};
if (!TOKEN) { throw new Error('Falta HERMES_TOKEN en el entorno de n8n'); }
if ((cabeceras['x-hermes-token'] || '') !== TOKEN) { throw new Error('Token invalido'); }
const estado = $getWorkflowStaticData('global');
estado.lotes = estado.lotes || {};
const lote = String(cuerpo.lote || 'sin-lote');

const info = estado.lotes[lote] || {};
info.cerrado = true;
info.terminado = Date.now();
const resumen = cuerpo.resumen || {};
const clases = cuerpo.clasificaciones || {};
const errores = Array.isArray(cuerpo.errores) ? cuerpo.errores : [];
const dudosos = Number(cuerpo.dudosos || 0);
const minutos = info.iniciado ? Math.round((Date.now() - info.iniciado) / 60000) : 0;
const fila = (o) => Object.entries(o).map(([k, v]) => `| ${k} | ${v} |`).join('\n');

const informe = [
  `# Lote ${lote}`, '',
  `- host: ${info.host || cuerpo.host || '?'}`,
  `- duracion: ${minutos} min`,
  `- archivos inventariados: ${(info.inventario || {}).nuevos ?? '?'}`, '',
  '## Estado', '', '| estado | n |', '| --- | ---: |', fila(resumen), '',
  '## Clasificacion', '', '| clase | n |', '| --- | ---: |', fila(clases), '',
  dudosos ? `## Pendiente de revision\n\nQuedan **${dudosos}** archivos dudosos. Resuelvelos en el PC con:\n\n\`\`\`\npython hermes_brain.py revisar --lote ${lote}\n\`\`\`\n` : '',
  errores.length ? `## Errores (${errores.length})\n\n` + errores.map(e => `- \`${e.id}\`: ${e.error}`).join('\n') : '',
].join('\n');

const aviso = `Hermes/brain — lote ${lote} terminado en ${minutos} min: ` +
  `${resumen.hecho || 0} procesados, ${resumen.omitido || 0} omitidos, ` +
  `${dudosos} dudosos por revisar, ${resumen.error || 0} errores.`;

return [{ json: { ok: true, lote, informe, aviso, resumen, clasificaciones: clases,
                  dudosos, errores: errores.length } }];

// Vigilancia: avisa si un lote abierto dejo de dar senales de vida.
// === CONFIG ===
const MINUTOS_SIN_LATIDO = 45;

const estado = $getWorkflowStaticData('global');
const lotes = estado.lotes || {};
const salida = [];
for (const [lote, info] of Object.entries(lotes)) {
  if (!info || info.cerrado) { continue; }
  const minutos = Math.round((Date.now() - (info.ultimo_latido || 0)) / 60000);
  if (minutos >= MINUTOS_SIN_LATIDO) {
    salida.push({ json: {
      lote, minutos, host: info.host || '?',
      procesados: info.procesados || 0,
      aviso: `Hermes/brain — el lote ${lote} lleva ${minutos} min sin reportar ` +
             `(${info.procesados || 0} archivos procesados). Revisa el worker en ${info.host || 'el PC'}.`,
    } });
  }
}
return salida;   // sin items = todo en orden, la rama no continua
